<template><div class="line-chart"><div class="chart-legend"><span v-for="item in series" :key="item.key"><i :style="{background:item.color}"/>{{item.label}}</span></div><svg viewBox="0 0 760 270" role="img" aria-label="最近十四天运行趋势"><g class="grid"><line v-for="y in [35,85,135,185,235]" :key="y" x1="42" :y1="y" x2="742" :y2="y"/></g><g v-for="item in series" :key="item.key"><polyline :points="points(item.key)" fill="none" :stroke="item.color" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle v-for="(point,index) in coordinates(item.key)" :key="index" :cx="point.x" :cy="point.y" r="4" :fill="item.color"><title>{{shortDay(data[index]?.day)}} · {{item.label}} {{data[index]?.[item.key]||0}}</title></circle></g><g class="axis"><text v-for="item in labels" :key="item.index" :x="item.x" y="260" text-anchor="middle">{{item.label}}</text></g></svg></div></template>
<script setup>import{computed}from"vue";const props=defineProps({data:{type:Array,default:()=>[]}}),series=[{key:"success",label:"同步成功",color:"#22c55e"},{key:"warning",label:"需要留意",color:"#f59e0b"},{key:"error",label:"运行失败",color:"#ef4444"}],maxValue=computed(()=>Math.max(4,...props.data.flatMap(row=>series.map(item=>Number(row[item.key]||0))))),coordinates=key=>props.data.map((row,index)=>({x:42+(700*Math.max(index,0))/Math.max(props.data.length-1,1),y:235-(Number(row[key]||0)/maxValue.value)*200})),points=key=>coordinates(key).map(point=>`${point.x},${point.y}`).join(" "),shortDay=value=>value?value.slice(5).replace("-","/"):"",labels=computed(()=>props.data.map((row,index)=>({index,x:42+(700*index)/Math.max(props.data.length-1,1),label:shortDay(row.day)})).filter((_,index)=>index===0||index===props.data.length-1||index%3===0));</script>
<style scoped>.line-chart{min-width:0}.chart-legend{display:flex;justify-content:flex-end;gap:16px;margin-bottom:8px;color:var(--fm-ink-muted);font-size:11px}.chart-legend span{display:flex;align-items:center;gap:6px}.chart-legend i{width:8px;height:8px;border-radius:50%}svg{display:block;width:100%;height:auto;overflow:visible}.grid line{stroke:var(--fm-line-soft);stroke-width:1}.axis text{fill:var(--fm-ink-muted);font-size:10px}</style>
